def build_error_summary(row):
    if row['SLA Breach'] == 1 and row['Missing Escalation'] == 1:
        return 'SLA Breach, Missing Escalation'
    if row['SLA Breach'] == 1:
        return 'SLA Breach'
    if row['Missing Escalation'] == 1:
        return 'Missing Escalation'
    return 'None'

